with matched_keys as (select id, device_code from device_readings intersect all select id, device_code from device_readings where status_bits = 11), kept_rows as (select s.* from device_readings s inner join matched_keys k on s.id = k.id and s.device_code = k.device_code) select device_code, case when humidity >= 68 then 'LARGE' else 'SMALL' end as humidity_tier, count_if(device_code = 'DV-04') as dv_04_events, size(collect_set(device_code)) as num_device_codes from kept_rows group by device_code, case when humidity >= 68 then 'LARGE' else 'SMALL' end
